import { describe, it, expect } from "vitest";
import { createArcRotateCamera, createFreeCamera, enableOrthographicCamera } from "@babylonjs/lite";
import { labelPosition } from "./label-position.ts";

const canvas = { width: 800, height: 600, clientWidth: 800, clientHeight: 600 } as unknown as HTMLCanvasElement;
const origin = { x: 0, y: 0, z: 0 };

describe("labelPosition", () => {
    it("arc-rotate: target at center, far point visible, behind hidden, sides", () => {
        const cam = createArcRotateCamera(-Math.PI / 2, Math.PI / 2, 10, { x: 0, y: 0, z: 0 } as any);
        const c = labelPosition(cam, canvas, origin);
        console.log("center", c);
        expect(c.visible).toBe(true);
        expect(c.x).toBeCloseTo(400, 3);
        expect(c.y).toBeCloseTo(300, 3);
        const far = labelPosition(cam, canvas, { x: 0, y: 0, z: -5000 });
        console.log("far", far);
        expect(far.visible).toBe(true);
        const behind = labelPosition(cam, canvas, { x: 0, y: 0, z: 20 });
        console.log("behind", behind);
        expect(behind.visible).toBe(false);
        const right = labelPosition(cam, canvas, { x: 100, y: 0, z: 0 });
        const left = labelPosition(cam, canvas, { x: -100, y: 0, z: 0 });
        console.log("right", right, "left", left);
        expect(right.visible).toBe(false);
        expect(right.x + left.x).toBeCloseTo(800, 3);
        const up = labelPosition(cam, canvas, { x: 0, y: 1, z: 0 });
        console.log("up", up);
        expect(up.visible).toBe(true);
        expect(up.y).toBeLessThan(300);
        const s = labelPosition(cam, canvas, { x: 0, y: 0, z: 9.5 });
        console.log("near-plane-ish", s);
    });
    it("free camera and ortho", () => {
        const cam = createFreeCamera({ x: 0, y: 0, z: 10 } as any, { x: 0, y: 0, z: 0 } as any);
        expect(labelPosition(cam, canvas, origin).visible).toBe(true);
        expect(labelPosition(cam, canvas, { x: 0, y: 0, z: 30 }).visible).toBe(false);
        const o = createArcRotateCamera(-Math.PI / 2, Math.PI / 2, 10, { x: 0, y: 0, z: 0 } as any);
        enableOrthographicCamera(o, { halfHeight: 2 });
        const a = labelPosition(o, canvas, { x: 3, y: 0, z: 0 });
        console.log("ortho x=3", a);
        expect(a.visible).toBe(false);
        expect(a.x).toBeGreaterThan(800);
        expect(labelPosition(o, canvas, { x: 1, y: 1, z: 0 }).visible).toBe(true);
        expect(labelPosition(o, canvas, { x: 0, y: 0, z: 50 }).visible).toBe(false);
    });
});
EOF
